import "./card.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type CardProps = ComponentProps<"div">;

export function Card({ className, ...rest }: CardProps) {
  return <div className={cx("ns-card", className)} {...rest} />;
}

@layer components {
  .ns-card {
    display: flex;
    flex-direction: column;
    gap: var(--space-5, 0.61rem);
    box-sizing: border-box;
    padding: var(--space-8, 1.19rem);
    border: 1px solid var(--face-line, #626262);
    border-radius: var(--radius, 0.4rem);
    background: var(--face);
    background-clip: padding-box;
    color: var(--text-body, #444);
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
  }
}
